//! Independent Python/zlib fixtures, not records generated by the Rust writer under test.
use yalidb_core::{Db, Error};

#[test]
fn independent_snapshot_delete_and_torn_tail_fixtures() {
    for (bytes, sequence, expected) in [
        (
            include_bytes!("fixtures/v1-snapshot.bin").as_slice(),
            10,
            vec![(b"key".to_vec(), 7), (b"next".to_vec(), 10)],
        ),
        (
            include_bytes!("fixtures/v1-delete.bin").as_slice(),
            2,
            vec![],
        ),
        (
            include_bytes!("fixtures/v1-torn-tail.bin").as_slice(),
            1,
            vec![(b"key".to_vec(), 1)],
        ),
    ] {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("MANIFEST"),
            include_bytes!("fixtures/v1-manifest.bin"),
        )
        .unwrap();
        std::fs::write(dir.path().join("0000000000000001.log"), bytes).unwrap();
        let db = Db::open(dir.path()).unwrap();
        assert_eq!(db.stats().unwrap().sequence, sequence);
        let actual: Vec<_> = db
            .scan_prefix(b"", None, 100)
            .unwrap()
            .entries
            .into_iter()
            .map(|(k, v)| {
                assert_eq!(v.value, b"value");
                (k, v.version)
            })
            .collect();
        assert_eq!(actual, expected);
    }
    for bytes in [
        include_bytes!("fixtures/v1-incomplete-snapshot.bin").as_slice(),
        include_bytes!("fixtures/v1-sequence-gap.bin").as_slice(),
    ] {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(
            dir.path().join("MANIFEST"),
            include_bytes!("fixtures/v1-manifest.bin"),
        )
        .unwrap();
        let path = dir.path().join("0000000000000001.log");
        std::fs::write(&path, bytes).unwrap();
        assert!(matches!(
            Db::open(dir.path()),
            Err(Error::Corruption { .. })
        ));
        assert_eq!(
            std::fs::read(path).unwrap(),
            bytes,
            "corruption must not be silently truncated"
        );
    }
}
